const tbMod = game.modules.get("pf2e-toolbelt");

if (!tbMod?.active) {
	ui.notifications.warn("The module <strong>PF2e Toolbelt</strong> is not active");
	return;
}

const heroActions = game.toolbelt?.api?.heroActions;

if (!heroActions?.removeHeroActions) {
	ui.notifications.error("PF2e Toolbelt heroActions API not found (game.toolbelt.api.heroActions.removeHeroActions).");
	return;
}

await heroActions.removeHeroActions();
